"""Topic research engine for WordPress AI Content system."""

import logging
import json
import re
from typing import List, Dict, Any
from app.models import ResearchResult
from app.llm import call_llm

logger = logging.getLogger(__name__)

_VALID_DEPTHS = {"basic", "comprehensive"}


class TopicResearcher:
    """Core topic research engine — all data generated by the LLM."""

    def research(self, topic: str, depth: str = "basic") -> ResearchResult:
        """Conduct in-depth LLM-powered research on a topic."""
        if not topic or not topic.strip():
            raise ValueError("Topic cannot be empty.")
        if depth not in _VALID_DEPTHS:
            raise ValueError(f"depth must be one of {_VALID_DEPTHS}, got '{depth}'.")

        try:
            logger.info(f"Researching topic: '{topic}' (depth: {depth})")

            key_findings = self._generate_key_findings(topic, depth)
            competitor_analysis = self._generate_competitor_analysis(topic)
            trends = self._generate_trends(topic, depth)
            sources = self._generate_sources(topic)
            recommendations = self._generate_research_recommendations(topic, key_findings)

            return ResearchResult(
                topic=topic,
                depth=depth,
                key_findings=key_findings,
                competitor_analysis=competitor_analysis,
                trends=trends,
                sources=sources,
                recommendations=recommendations,
            )
        except (ValueError, RuntimeError):
            raise
        except Exception as e:
            logger.error(f"Error researching topic '{topic}': {e}")
            raise RuntimeError(f"Failed to research topic: {e}")

    # ------------------------------------------------------------------

    def _generate_key_findings(self, topic: str, depth: str) -> List[str]:
        """Generate key facts and findings using the LLM."""
        count = 8 if depth == "comprehensive" else 5
        prompt = f"""Actúa como un investigador de contenido experto.
Genera {count} hallazgos clave, datos o hechos relevantes sobre el tema: "{topic}".
{'Sé exhaustivo y técnico, incluye estadísticas y tendencias actuales.' if depth == 'comprehensive' else 'Sé conciso y enfocado en los puntos más importantes.'}

Responde ÚNICAMENTE con una lista numerada de {count} puntos, sin introducción ni conclusión.
Ejemplo de formato:
1. Primer hallazgo importante.
2. Segundo hallazgo importante."""
        try:
            res = call_llm(prompt)
            lines = [
                re.sub(r'^\d+[\.\)]\s*', '', line).strip()
                for line in res.split("\n")
                if line.strip() and re.match(r'^\d', line.strip())
            ]
            return lines if lines else [f"Hallazgo clave sobre {topic}."]
        except Exception as e:
            logger.warning(f"LLM key findings failed: {e}")
            return [f"Investigación sobre {topic} disponible bajo petición."]

    def _generate_competitor_analysis(self, topic: str) -> List[Dict[str, Any]]:
        """Generate competitor/reference site analysis using the LLM."""
        prompt = f"""Analiza el panorama competitivo de contenido web para el tema: "{topic}".
Identifica 3 tipos de sitios o publicaciones que dominan este nicho.

Responde ÚNICAMENTE con un JSON válido con esta estructura (sin bloques markdown):
[
  {{"competitor": "Nombre del sitio/medio", "strength": "Su principal fortaleza de contenido", "weakness": "Su principal debilidad o brecha"}},
  {{"competitor": "...", "strength": "...", "weakness": "..."}}
]"""
        try:
            res = call_llm(prompt, max_tokens=500)
            cleaned = res.strip()
            if cleaned.startswith("```"):
                cleaned = re.sub(r'^```[a-z]*\n?', '', cleaned)
                cleaned = re.sub(r'\n?```$', '', cleaned).strip()
            return json.loads(cleaned)
        except Exception as e:
            logger.warning(f"LLM competitor analysis failed: {e}")
            return [
                {"competitor": "Blogs especializados en " + topic, "strength": "Alta autoridad de dominio", "weakness": "Actualizaciones poco frecuentes"},
                {"competitor": "Medios técnicos generalistas", "strength": "Gran audiencia", "weakness": "Profundidad técnica limitada"},
            ]

    def _generate_trends(self, topic: str, depth: str = "basic") -> List[str]:
        """Generate current trends using the LLM."""
        count = 5 if depth == "comprehensive" else 3
        prompt = f"""¿Cuáles son las {count} tendencias actuales más importantes relacionadas con "{topic}"?
Sé específico y menciona tecnologías, herramientas o cambios de mercado concretos.

Responde ÚNICAMENTE con una lista numerada de {count} tendencias, sin introducción."""
        try:
            res = call_llm(prompt)
            lines = [
                re.sub(r'^\d+[\.\)]\s*', '', line).strip()
                for line in res.split("\n")
                if line.strip() and re.match(r'^\d', line.strip())
            ]
            return lines if lines else [f"Tendencia en adopción de {topic}"]
        except Exception as e:
            logger.warning(f"LLM trends failed: {e}")
            return [f"Creciente adopción de {topic}"]

    def _generate_sources(self, topic: str) -> List[str]:
        """Generate relevant reference sources using the LLM."""
        prompt = f"""Sugiere 5 fuentes de información confiables y relevantes para investigar sobre "{topic}".
Incluye sitios de noticias tecnológicas, repositorios, o documentación oficial relevante.

Responde ÚNICAMENTE con una lista numerada de 5 URLs o nombres de fuentes, sin introducción."""
        try:
            res = call_llm(prompt, max_tokens=300)
            lines = [
                re.sub(r'^\d+[\.\)]\s*', '', line).strip()
                for line in res.split("\n")
                if line.strip() and re.match(r'^\d', line.strip())
            ]
            return lines if lines else ["https://techcrunch.com", "https://github.com", "https://coindesk.com"]
        except Exception as e:
            logger.warning(f"LLM sources failed: {e}")
            return ["https://techcrunch.com", "https://github.com", "https://coindesk.com"]

    def _generate_research_recommendations(self, topic: str, findings: List[str]) -> List[str]:
        """Generate actionable content recommendations based on research findings."""
        findings_text = "\n".join(f"- {f}" for f in findings[:5])
        prompt = f"""Basándote en estos hallazgos de investigación sobre "{topic}":
{findings_text}

Genera 3 recomendaciones concretas de contenido (artículos, guías o análisis) que sería valioso publicar.

Responde ÚNICAMENTE con una lista numerada de 3 recomendaciones, sin introducción."""
        try:
            res = call_llm(prompt, max_tokens=300)
            lines = [
                re.sub(r'^\d+[\.\)]\s*', '', line).strip()
                for line in res.split("\n")
                if line.strip() and re.match(r'^\d', line.strip())
            ]
            return lines if lines else [
                f"Crea una guía completa sobre {topic}",
                f"Analiza los desafíos y soluciones en {topic}",
            ]
        except Exception as e:
            logger.warning(f"LLM recommendations failed: {e}")
            return [
                f"Crea una guía completa sobre {topic}",
                f"Escribe un análisis de casos de uso en {topic}",
            ]
